/* VEYA-AI Theme: Dark Neon */

:root {
  /* Backgrounds */
  --background-primary: #0d0d14;
  --background-secondary: #111118;
  --background-secondary-alt: #0a0a10;
  --background-tertiary: #080810;
  --background-accent: #5865f2;
  --background-floating: #111118;
  --background-nested-floating: #1a1a24;

  /* Modifiers */
  --background-modifier-hover: rgba(88, 101, 242, 0.08);
  --background-modifier-active: rgba(88, 101, 242, 0.16);
  --background-modifier-selected: rgba(88, 101, 242, 0.24);
  --background-modifier-accent: rgba(255, 255, 255, 0.06);

  /* Text */
  --text-normal: #dcddde;
  --text-muted: #72767d;
  --text-link: #7289da;
  --header-primary: #ffffff;
  --header-secondary: #b9bbbe;

  /* Interaction */
  --interactive-normal: #b9bbbe;
  --interactive-hover: #dcddde;
  --interactive-active: #ffffff;
  --interactive-muted: #4f545c;

  /* Brand / accent */
  --brand-500: #7c5cbf;
  --brand-560: #6a4fad;

  /* Channels */
  --channeltextarea-background: #1a1a24;
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #2a2a3a; border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #7c5cbf; }

/* Channel list – subtle glow on hover */
[class*="channel-"]:hover [class*="name-"] {
  color: #c0a8ff !important;
}
